import json
DS = {"type": "data_view_spec", "index_pattern": "kibana_sample_data_logs", "time_field": "timestamp"}
STYLE = {"primary": {"labels": {"alignment": "left", "position": "bottom"}, "value": {"alignment": "right", "sizing": "auto"}}}

