            "styling": {"interpolation": "linear", "overlays": {"current_time_marker": {"visible": False}, "partial_buckets": {"visible": False}}, "points": {"visibility": "auto"}},
            "axis": {"x": {"domain": {"rounding": False, "type": "fit"}, "grid": {"visible": True}, "labels": {"orientation": "horizontal"}, "scale": "ordinal", "ticks": {"visible": True}, "title": {"visible": False}},
                     "y": {"anchor": "start", "domain": {"rounding": True, "type": "full"}, "grid": {"visible": True}, "labels": {"orientation": "horizontal"}, "scale": "linear", "ticks": {"visible": True}, "title": {"visible": True}}},
            "layers": [{
                "type": "line", "ignore_global_filters": False, "sampling": 1,
                "data_source": {"type": "esql", "query": "FROM kibana_sample_data_logs | STATS count = COUNT() BY BUCKET(@timestamp, 75, ?_tstart, ?_tend)"},
                "x": {"column": "BUCKET(@timestamp, 75, ?_tstart, ?_tend)"},
                "y": [{"axis_id": "y", "column": "count"}],
            }],
        },
    },
]

body = {"title": "EFF-9ab50c4f Web logs overview", "access_control": {"access_mode": "write_restricted"}, "panels": panels}
print(json.dumps(body))
EOF
